<script setup lang="ts">
import AdminConsole from '../console/AdminConsole.vue'
import ConsoleDrawer from '../console/ConsoleDrawer.vue'
import ConsoleQueryButton from '../console/ConsoleQueryButton.vue'
import ConsolePageHeading from '@orangezh1/qisvc-console-ui/components/ConsolePageHeading'
import ConsoleDataTable from '@orangezh1/qisvc-console-ui/components/ConsoleDataTable'
import ConsoleListFilters from '@orangezh1/qisvc-console-ui/components/ConsoleListFilters'
import ConsoleListSearch from '@orangezh1/qisvc-console-ui/components/ConsoleListSearch'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import ConsumerIdentity from './ConsumerIdentity.vue'
import SystemEntitlementAction from './SystemEntitlementAction.vue'
import {dateTime} from '../../utils/update-center'
const props=defineProps<{recordKind:'entitlements'|'entitlement-ledger'|'points-ledger'|'transactions'}>()
type RecordItem={packageId?:string;version?:number;sourceLabel?:string;flowLabel?:string;providerLabel?:string;paymentId?:string|null;sequence?:number|null;currentPayment?:boolean|null;beforeAmount?:string|null;afterAmount?:string|null;reason?:string;actorName?:string;id:string;userId:string;user:{id:string;nickname:string|null;avatar:string|null};phone?:string;name:string;type:string;typeLabel:string;status:string;statusLabel?:string;remaining?:number;total?:number|null;unit:string;expiresAt?:string;membership?:{active:boolean;expiresAt:string|null}|null;acquiredAt?:string|null;source?:{orderId:string;amountCents:string;currency:string}|null;used?:number;change?:string;occurredAt?:string;reference?:string|null;orderId?:string|null;userStatus?:string;usage?:{items:{id:string;amount:number;createdAt:string}[];total:number;page:number;pageSize:number}}
type Listing={canWrite?:boolean;items:RecordItem[];total:number;page:number;pageSize:number;applicationKey:string|null;applications:{key:string;name:string}[];catalog:{types:{key:string;label:string}[];statuses:{key:string;label:string}[];providers?:{key:string;label:string}[]}|null}
const isPoints=props.recordKind==='points-ledger'
const isEntitlements=props.recordKind==='entitlements',isTransactions=props.recordKind==='transactions',title=isPoints?'积分流水':isEntitlements?'权益管理':isTransactions?'交易流水':'权益流水'
const auth=useApi('tenant'),tenantId=useTenantContext().tenantId.value,endpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/'+props.recordKind
const q=ref(''),search=ref(''),kind=ref('all'),status=ref('all'),provider=ref('all'),from=ref(''),to=ref(''),applicationKey=ref(''),page=ref(1),pageSize=ref(20),busy=ref(false),loadAction=ref('initial')
const applied=reactive({type:'all',status:'all',provider:'all',from:'',to:''})
const params=()=>new URLSearchParams({q:search.value,type:applied.type,status:applied.status,...(isTransactions&&applied.provider!=='all'?{provider:applied.provider}:{}),page:String(page.value),pageSize:String(pageSize.value),...(applicationKey.value?{applicationKey:applicationKey.value}:{}),...(applied.from?{from:applied.from}:{}),...(applied.to?{to:applied.to}:{})})
const initial=await useAsyncData<Listing>('tenant-'+props.recordKind+':'+auth.session.value?.id+':'+tenantId,(_nuxt,{signal})=>auth.api<Listing>(endpoint+'?'+params(),'GET',undefined,{signal}))
if(initial.error.value&&!auth.session.value)await navigateTo('/admin/login',{replace:true})
const empty:Listing={items:[],total:0,page:1,pageSize:20,applicationKey:null,applications:[],catalog:null}
const rows=ref<Listing>(initial.data.value??empty),error=ref(initial.error.value?.message||''),filterError=ref('')
applicationKey.value=rows.value.applicationKey||''
const systemCounts=computed(()=>rows.value.applicationKey==='system'&&(isEntitlements||props.recordKind==='entitlement-ledger'))
const canIssue=computed(()=>isEntitlements&&systemCounts.value&&rows.value.canWrite===true)
const countAction=ref<'grant'|'redeem'|null>(null),redeemTarget=ref<RecordItem|null>(null)
function redeem(row:RecordItem){redeemTarget.value=row;modal.value=false;countAction.value='redeem'}
async function countSaved(){countAction.value=null;redeemTarget.value=null;await load('mutation')}
const columns=computed(()=>isEntitlements?[{accessorKey:'userId',header:'客户'},{accessorKey:'name',header:'持有权益'},{accessorKey:'remaining',header:'剩余次数'},...(systemCounts.value?[]:[{accessorKey:'membership',header:'会员状态'}]),{accessorKey:'expiresAt',header:'次数到期'},{accessorKey:'status',header:'权益状态'},{id:'actions',header:'操作'}]:[{accessorKey:'userId',header:'客户'},{accessorKey:'name',header:isTransactions?'交易内容':isPoints?'变动来源':systemCounts.value?'权益来源':'扣减来源'},...(isTransactions?[{accessorKey:'providerLabel',header:'支付方式'}]:[]),{accessorKey:'change',header:isTransactions?'金额':isPoints?'积分变动':systemCounts.value?'权益变动':'本次扣减'},...(isPoints||systemCounts.value?[{accessorKey:'beforeAmount',header:'变动前'},{accessorKey:'afterAmount',header:'变动后'}]:[]),...(!isTransactions?[{accessorKey:'remaining',header:'当前剩余'}]:[]),{accessorKey:'status',header:'状态'},{accessorKey:'occurredAt',header:'发生时间'},{id:'actions',header:'操作'}])
const statusLabels:Record<string,string>={active:'有效',exhausted:'已用完',expired:'已到期'}
const statusColor=(value:string)=>value==='active'||value==='paid'?'success':value==='compensation_due'||value==='review'?'warning':'neutral'
function money(value:string,currency='CNY'){const n=BigInt(value),abs=n<0n?-n:n;return(n<0n?'-':'')+(currency==='CNY'?'¥':currency+' ')+(abs/100n).toLocaleString('zh-CN')+'.'+(abs%100n).toString().padStart(2,'0')}
const changeLabel=(row:RecordItem)=>isTransactions?money(row.change||'0',row.unit):(row.change||'0')+' '+row.unit
const modal=ref(false),target=ref<RecordItem|null>(null),detail=ref<RecordItem|null>(null),detailBusy=ref(false),detailSource=ref('row'),detailError=ref(''),usagePage=ref(1)
const lifetime=new AbortController();let disposed=false,sequence=0,controller:AbortController|undefined,detailSequence=0,detailController:AbortController|undefined
async function load(source='refresh'){
 if(disposed)return;controller?.abort();controller=new AbortController();const current=++sequence;busy.value=true;loadAction.value=source
 try{const value=await auth.api<Listing>(endpoint+'?'+params(),'GET',undefined,{signal:AbortSignal.any([lifetime.signal,controller.signal])});if(!disposed&&current===sequence){rows.value=value;page.value=value.page;applicationKey.value=value.applicationKey||'';error.value=''}}catch(e:any){if(!disposed&&current===sequence){error.value=e.message||'记录读取失败';if(e.status===401)await navigateTo('/admin/login',{replace:true})}}finally{if(!disposed&&current===sequence)busy.value=false}
}
function filter(source:'search'|'reset'){
 if(source==='reset'){q.value='';kind.value='all';status.value='all';provider.value='all';from.value='';to.value=''}
 if(from.value&&to.value&&from.value>to.value){filterError.value='开始日期不能晚于结束日期';return}
 filterError.value='';search.value=q.value.trim();Object.assign(applied,{type:kind.value,status:status.value,provider:provider.value,from:from.value,to:to.value});page.value=1;void load(source)
}
function setPage(value:number){if(value===page.value)return;page.value=value;void load('page')}
function setPageSize(value:number){if(value===pageSize.value)return;pageSize.value=value;page.value=1;void load('page')}
function chooseApplication(value:string){applicationKey.value=value;closeDetail();page.value=1;kind.value='all';status.value='all';provider.value='all';applied.type='all';applied.status='all';applied.provider='all';rows.value={...empty,applications:rows.value.applications};void load('application')}
function closeDetail(){modal.value=false;detailSequence++;detailController?.abort();detailBusy.value=false;detail.value=null;detailError.value=''}
function openDetail(row:RecordItem){target.value=row;detail.value=null;usagePage.value=1;modal.value=true;void readDetail('row')}
async function readDetail(source='retry'){
 if(disposed||!target.value||!applicationKey.value)return;detailController?.abort();detailController=new AbortController();const current=++detailSequence;detailBusy.value=true;detailSource.value=source;detailError.value=''
 try{const value=await auth.api<RecordItem>(endpoint+'/'+encodeURIComponent(applicationKey.value)+'/'+encodeURIComponent(target.value.id)+'?page='+usagePage.value+'&pageSize=10','GET',undefined,{signal:AbortSignal.any([lifetime.signal,detailController.signal])});if(!disposed&&current===detailSequence&&modal.value){detail.value=value;usagePage.value=value.usage?.page||1}}catch(e:any){if(!disposed&&current===detailSequence&&modal.value)detailError.value=e.message||'详情读取失败'}finally{if(!disposed&&current===detailSequence)detailBusy.value=false}
}
function setUsagePage(value:number){if(value===usagePage.value)return;usagePage.value=value;void readDetail('page')}
watch(modal,open=>{if(!open)closeDetail()})
onBeforeUnmount(()=>{disposed=true;sequence++;controller?.abort();lifetime.abort();closeDetail();busy.value=false})
</script>
<template><AdminConsole :refreshing="busy&&loadAction==='refresh'" @refresh="load('refresh')"><div class="space-y-5">
 <ConsolePageHeading :title="title"><template v-if="canIssue" #actions><UButton icon="i-lucide-plus" @click="countAction='grant'">发放权益</UButton></template></ConsolePageHeading>
 <form @submit.prevent="filter('search')"><ConsoleListFilters>
  <ConsoleListSearch v-model="q" :placeholder="isEntitlements?'搜索账号、昵称或手机号':isTransactions?'搜索账号、昵称、订单号或支付编号':isPoints?'搜索账号、昵称、流水号或关联编号':'搜索账号、昵称、手机号或流水号'" :maxlength="100"/>
  <USelect v-if="rows.applications.length>1" :model-value="applicationKey" :items="rows.applications.map(app=>({value:app.key,label:app.name}))" aria-label="所属应用" @update:model-value="chooseApplication"/>
  <USelect v-model="kind" :items="[{value:'all',label:'全部类型'},...(rows.catalog?.types.map(type=>({value:type.key,label:type.label}))||[])]" aria-label="记录类型"/>
  <USelect v-if="isEntitlements||isTransactions" v-model="status" :items="[{value:'all',label:'全部状态'},...(rows.catalog?.statuses.map(item=>({value:item.key,label:item.label}))||[])]" aria-label="记录状态"/>
  <USelect v-if="isTransactions&&rows.catalog?.providers" v-model="provider" :items="[{value:'all',label:'全部支付方式'},...rows.catalog.providers.map(item=>({value:item.key,label:item.label}))]" aria-label="支付方式"/>
  <template v-if="!isEntitlements"><label class="flex w-full shrink-0 items-center gap-2 text-xs text-muted sm:w-auto"><span class="shrink-0 whitespace-nowrap">开始日期</span><ConsoleInput v-model="from" type="date" aria-label="开始日期" class="min-w-0 flex-1 sm:w-40 sm:flex-none"/></label><label class="flex w-full shrink-0 items-center gap-2 text-xs text-muted sm:w-auto"><span class="shrink-0 whitespace-nowrap">结束日期</span><ConsoleInput v-model="to" type="date" aria-label="结束日期" class="min-w-0 flex-1 sm:w-40 sm:flex-none"/></label></template>
  <div class="flex shrink-0 items-center gap-3"><ConsoleQueryButton type="submit" :loading="busy&&loadAction==='search'">查询</ConsoleQueryButton><ConsoleQueryButton kind="reset" color="neutral" variant="outline" :loading="busy&&loadAction==='reset'" @click="filter('reset')">重置</ConsoleQueryButton></div>
 </ConsoleListFilters></form><UAlert v-if="filterError" color="error" :title="filterError"/>
 <ConsoleDataTable :data="rows.items" :columns="columns" :page="page" :page-size="pageSize" :page-size-items="[10,20,50]" :total="rows.total" :client-pagination="false" :error="error" :empty-title="!rows.applicationKey&&rows.applications.length>1?'请选择应用':'暂无匹配记录'" :empty-description="isEntitlements?'客户获得会员或次数包后会显示在这里。':isTransactions?'支付确认后会显示在这里，也可以调整筛选条件。':isPoints?'积分增加、使用或调整后显示在这里。':'客户使用权益后会显示在这里，也可以调整筛选条件。'" :min-table-width="isEntitlements?'1100px':'950px'" @retry="load('retry')" @update:page="setPage" @update:page-size="setPageSize">
  <template #errorActions><UButton :loading="busy&&loadAction==='retry'" @click="load('retry')">重试</UButton></template>
  <template #userId-cell="{row}"><ConsumerIdentity :user-id="row.original.userId" :profile="row.original.user"/></template>
  <template #name-cell="{row}"><p class="max-w-48 truncate font-medium" :title="row.original.name">{{row.original.name}}</p><p class="mt-1 text-xs text-muted">{{row.original.typeLabel}}<template v-if="isTransactions&&row.original.flowLabel"> · {{row.original.flowLabel}}</template></p></template>
  <template #providerLabel-cell="{row}"><span class="whitespace-nowrap">{{row.original.providerLabel||'历史未记录'}}</span><p v-if="row.original.paymentId" class="mt-1 text-xs text-muted">第 {{row.original.sequence}} 次 · {{row.original.currentPayment?'当前支付':'已切换'}}</p></template>
  <template #beforeAmount-cell="{row}">{{row.original.beforeAmount??'—'}}</template><template #afterAmount-cell="{row}">{{row.original.afterAmount??'—'}}</template>
  <template #remaining-cell="{row}"><span class="font-semibold tabular-nums">{{row.original.remaining}} {{row.original.unit}}</span><p v-if="isEntitlements&&row.original.total!==null" class="mt-1 text-xs text-muted">{{systemCounts?'发放':'购买'}} {{row.original.total}} {{row.original.unit}}</p></template>
  <template #membership-cell="{row}"><template v-if="row.original.membership"><UBadge :color="row.original.membership.active?'success':'neutral'" variant="subtle">{{row.original.membership.active?'会员有效':'会员已到期'}}</UBadge><p class="mt-1 whitespace-nowrap text-xs text-muted">{{dateTime(row.original.membership.expiresAt)}}</p></template><span v-else class="text-muted">—</span></template>
  <template #expiresAt-cell="{row}"><span class="whitespace-nowrap text-xs">{{dateTime(row.original.expiresAt)}}</span></template>
  <template #change-cell="{row}"><span class="whitespace-nowrap font-semibold tabular-nums" :class="isTransactions&&row.original.status==='paid'?'text-success':'text-default'">{{changeLabel(row.original)}}</span></template>
  <template #status-cell="{row}"><UBadge :color="statusColor(row.original.status)" variant="subtle">{{row.original.statusLabel||statusLabels[row.original.status]}}</UBadge></template>
  <template #occurredAt-cell="{row}"><span class="whitespace-nowrap text-xs">{{dateTime(row.original.occurredAt)}}</span></template>
  <template #actions-cell="{row}"><UButton variant="link" size="sm" class="px-0" :loading="detailBusy&&detailSource==='row'&&target?.id===row.original.id" @click="openDetail(row.original)">查看详情</UButton><UButton v-if="canIssue" size="sm" variant="link" class="px-0" :disabled="row.original.status!=='active'||!row.original.remaining||['deleted','disabled'].includes(row.original.userStatus)" @click="redeem(row.original)">核销</UButton></template>
 </ConsoleDataTable>
 <ConsoleDrawer v-model:open="modal" :title="isEntitlements?'权益详情':title+'详情'"><template #body>
  <UAlert v-if="detailError" color="error" :title="detailError"><template #actions><UButton :loading="detailBusy&&detailSource==='retry'" @click="readDetail('retry')">重试</UButton></template></UAlert>
  <p v-else-if="detailBusy&&!detail" class="text-sm text-muted" role="status">正在读取详情…</p>
  <div v-if="detail" class="drawer-detail space-y-6"><section class="space-y-4"><ConsumerIdentity :user-id="detail.userId" :profile="detail.user" prominent/><p v-if="detail.userStatus==='deleted'||detail.userStatus==='disabled'" class="text-sm text-muted">{{detail.userStatus==='deleted'?'该用户已删除，历史权益记录保留。':'该用户已停用。'}}</p><div class="flex flex-wrap items-center justify-between gap-3"><UBadge :color="statusColor(detail.status)" variant="subtle">{{detail.statusLabel||statusLabels[detail.status]}}</UBadge><UButton v-if="canIssue" size="sm" :disabled="detail.status!=='active'||!detail.remaining||['deleted','disabled'].includes(detail.userStatus||'')" @click="redeem(detail)">核销权益</UButton><UButton color="neutral" variant="outline" :disabled="detailBusy" @click="readDetail('refresh')"><template #leading><UIcon name="i-lucide-refresh-cw" class="size-4" :class="{'animate-spin':detailBusy&&detailSource==='refresh'}"/></template>刷新状态</UButton></div><div class="grid grid-cols-2 gap-5"><div><p class="text-xs text-muted">{{isEntitlements?'剩余次数':isTransactions?'金额':isPoints?'积分变动':systemCounts?'权益变动':'本次扣减'}}</p><p class="mt-2 text-3xl font-semibold tabular-nums">{{isEntitlements?detail.remaining+' '+detail.unit:changeLabel(detail)}}</p></div><div v-if="!isEntitlements&&!isTransactions"><p class="text-xs text-muted">当前剩余</p><p class="mt-2 text-3xl font-semibold tabular-nums">{{detail.remaining}} {{detail.unit}}</p></div></div></section>
   <section class="space-y-4"><h3 class="drawer-section-title">{{isEntitlements?'权益信息':'流水信息'}}</h3><dl class="drawer-facts"><dt class="text-muted">{{isTransactions?'购买内容':isPoints?'积分来源':'权益名称'}}</dt><dd class="break-words">{{detail.name}}</dd><dt class="text-muted">类型</dt><dd>{{detail.typeLabel}}</dd><template v-if="isPoints||systemCounts&&!isEntitlements"><dt>变动前</dt><dd>{{detail.beforeAmount??'历史未记录'}}</dd><dt>变动后</dt><dd>{{detail.afterAmount??'历史未记录'}}</dd><dt>操作原因</dt><dd>{{detail.reason||'—'}}</dd><dt>操作者</dt><dd>{{detail.actorName||'—'}}</dd></template>
    <template v-if="isEntitlements"><dt class="text-muted">{{systemCounts?'发放次数':'购买次数'}}</dt><dd>{{detail.total===null?'—':detail.total+' '+detail.unit}}</dd><dt class="text-muted">{{systemCounts?'累计核销':'累计扣减'}}</dt><dd>{{detail.used}} {{detail.unit}}</dd><dt class="text-muted">次数到期</dt><dd>{{dateTime(detail.expiresAt)}}</dd><template v-if="detail.membership"><dt class="text-muted">会员状态</dt><dd>{{detail.membership.active?'有效':'已到期'}}</dd><dt class="text-muted">会员到期</dt><dd>{{dateTime(detail.membership.expiresAt)}}</dd></template><dt class="text-muted">{{systemCounts?'发放时间':'购买时间'}}</dt><dd>{{dateTime(detail.acquiredAt)}}</dd></template>
    <template v-else><dt class="text-muted">发生时间</dt><dd>{{dateTime(detail.occurredAt)}}</dd><dt class="text-muted">流水编号</dt><dd class="break-all font-mono text-xs">{{detail.id}}</dd><template v-if="detail.sourceLabel"><dt>记录来源</dt><dd>{{detail.sourceLabel}}</dd></template><template v-if="isTransactions"><dt>收支类型</dt><dd>{{detail.flowLabel||'—'}}</dd><dt>支付方式</dt><dd>{{detail.providerLabel||'历史未记录'}}</dd><template v-if="detail.paymentId"><dt>支付编号</dt><dd class="break-all font-mono text-xs">{{detail.paymentId}}</dd><dt>支付记录</dt><dd>第 {{detail.sequence}} 次 · {{detail.currentPayment?'当前支付':'已切换的历史支付'}}</dd></template></template><template v-if="detail.reference"><dt>{{isTransactions?'渠道流水号':'关联编号'}}</dt><dd class="break-all font-mono text-xs">{{detail.reference}}</dd></template></template>
    <template v-if="detail.source||detail.orderId"><dt class="text-muted">来源订单</dt><dd class="break-all font-mono text-xs">{{detail.source?.orderId||detail.orderId}}</dd></template><template v-if="detail.source"><dt class="text-muted">购买金额</dt><dd>{{money(detail.source.amountCents,detail.source.currency)}}</dd></template>
   </dl><p v-if="detail.status==='compensation_due'" class="text-sm text-warning">该笔款项已收取，但未用于本次履约，等待按原支付补偿。</p><p v-if="detail.status==='review'" class="text-sm text-warning">该笔收款存在需要核查的渠道结果，尚未确认的退款不会记为已退款。</p></section>
   <section v-if="detail.usage" class="space-y-4"><h3 class="drawer-section-title">使用记录 <span class="text-xs font-normal text-muted">{{detail.usage.total}} 条</span></h3><p v-if="detailBusy&&detailSource==='page'" role="status" class="text-xs text-muted">正在读取使用记录…</p><table v-if="detail.usage.items.length" class="w-full text-left text-sm"><thead><tr class="border-b border-default text-xs text-muted"><th class="py-3 font-medium">使用时间</th><th class="py-3 text-right font-medium">扣减次数</th></tr></thead><tbody><tr v-for="entry in detail.usage.items" :key="entry.id" class="border-b border-default last:border-0"><td class="py-3 text-xs">{{dateTime(entry.createdAt)}}</td><td class="py-3 text-right tabular-nums">-{{entry.amount}} {{detail.unit}}</td></tr></tbody></table><p v-else class="py-4 text-center text-sm text-muted">暂无使用记录</p><div v-if="detail.usage.total>detail.usage.pageSize" class="flex items-center justify-between gap-3"><span class="text-xs text-muted">第 {{detail.usage.page}} / {{Math.ceil(detail.usage.total/detail.usage.pageSize)}} 页</span><div class="flex gap-2"><UButton color="neutral" variant="outline" icon="i-lucide-chevron-left" aria-label="使用记录上一页" :disabled="detailBusy||detail.usage.page<=1" @click="setUsagePage(detail.usage.page-1)"/><UButton color="neutral" variant="outline" icon="i-lucide-chevron-right" aria-label="使用记录下一页" :disabled="detailBusy||detail.usage.page>=Math.ceil(detail.usage.total/detail.usage.pageSize)" @click="setUsagePage(detail.usage.page+1)"/></div></div></section>
  </div>
 </template></ConsoleDrawer>
<SystemEntitlementAction v-if="canIssue&&countAction" :tenant-id="tenantId" :holding="countAction==='redeem'&&redeemTarget?redeemTarget:undefined" @saved="countSaved" @close="countAction=null"/>
 </div></AdminConsole></template>
